    <p v-if="error" class="alert" role="alert">{{ error }}</p><p v-if="notice" class="notice" role="status">{{ notice }}</p>
    <div v-if="loading" class="loading">正在读取 RAG 评测报告…</div>
    <template v-else-if="report?.available">
