      <section class="summary" aria-label="RAG 评测摘要">
        <article><span>标注用例</span><strong>{{ report.summary.cases }}</strong><small>{{ report.contract.valid ? "契约完整" : "契约异常" }}</small></article>
        <article class="good"><span>字段 Recall@K</span><strong>{{ percent(route('column').recall_at_k) }}</strong><small>MRR {{ decimal(route('column').mrr) }}</small></article>
        <article :class="route('column').precision_at_k >= .4 ? 'good' : 'bad'"><span>字段 Precision@K</span><strong>{{ percent(route('column').precision_at_k) }}</strong><small>门槛 ≥ 40%</small></article>
        <article class="good"><span>筛表召回</span><strong>{{ percent(report.summary.table_filter_recall) }}</strong><small>候选阶段 {{ percent(report.summary.table_candidate_recall) }}</small></article>
        <article :class="report.summary.gate_passed ? 'good' : 'bad'"><span>展示字段命中</span><strong>{{ percent(report.summary.display_hit_rate) }}</strong><small>{{ report.summary.gate_passed ? "门禁通过" : "门禁失败" }}</small></article>
      </section>
      <section class="panel">
        <div class="panel-head"><div><h2>四路召回指标</h2><p>Recall@K 负责漏召回，Precision@K 反映上下文噪声，MRR / nDCG 反映排序质量。</p></div><span :class="report.summary.gate_passed ? 'pass' : 'fail'">{{ report.summary.gate_passed ? "门禁通过" : "门禁失败" }}</span></div>
        <div class="route-grid"><article v-for="name in routes" :key="name"><div><b>{{ routeLabel(name) }}</b><small>{{ route(name).cases }} 个适用问题</small></div><dl><div><dt>Recall@K</dt><dd>{{ percent(route(name).recall_at_k) }}</dd></div><div><dt>Precision@K</dt><dd>{{ percent(route(name).precision_at_k) }}</dd></div><div><dt>MRR</dt><dd>{{ decimal(route(name).mrr) }}</dd></div><div><dt>nDCG</dt><dd>{{ decimal(route(name).ndcg) }}</dd></div></dl></article></div>
      </section>
      <section class="panel comparison">
        <div class="panel-head"><div><h2>同集调优对比</h2><p>基线使用固定 K；调优版融合 exact/alias/lexical/vector 特征并按分差动态截断。</p></div></div>
        <div class="compare-grid"><article><span>字段 Recall@K</span><b>{{ percent(beforeSummary.routes.column.recall_at_k) }} → {{ percent(report.tuned.summary.routes.column.recall_at_k) }}</b><em>{{ signedPercent(report.comparison.column_recall_delta) }}</em></article><article><span>字段 Precision@K</span><b>{{ percent(beforeSummary.routes.column.precision_at_k) }} → {{ percent(report.tuned.summary.routes.column.precision_at_k) }}</b><em>{{ signedPercent(report.comparison.column_precision_delta) }}</em></article><article><span>展示字段</span><b>{{ percent(beforeSummary.display_hit_rate) }} → {{ percent(report.tuned.summary.display_hit_rate) }}</b><em>{{ signedPercent(report.comparison.display_hit_delta) }}</em></article><article><span>候选预算变化</span><b>{{ beforeSummary.candidate_count }} → {{ report.tuned.summary.candidate_count }}</b><em>{{ signed(report.comparison.candidate_count_delta) }}</em></article></div>
      </section>
      <section class="panel hybrid-panel">
        <div class="panel-head"><div><h2>BGE-M3 Dense + Sparse 实测</h2><p>同一模型分别跑 Dense、Sparse、实体级 RRF 与 RRF + 现有规则精排；旧 Dense 只作为覆盖前历史制品。</p></div><span :class="report.hybrid?.summary?.gate_passed ? 'pass' : 'fail'">{{ report.hybrid?.available ? (report.hybrid.summary.gate_passed ? "混合门禁通过" : "混合门禁未通过") : "尚无混合报告" }}</span></div>
        <template v-if="report.hybrid?.available">
          <div class="hybrid-meta"><code>{{ report.hybrid.active_mode }}</code><span>覆盖现有集合</span><span>v1 回退：关闭</span><span>{{ report.hybrid.contract.total }} 条</span><span>首轮 16 题 Recall {{ percent(hybridProfile("R-H3").base_column_recall_at_k) }} · Precision {{ percent(hybridProfile("R-H3").base_column_precision_at_k) }}</span></div>
          <div class="hybrid-grid"><article v-for="name in hybridProfiles" :key="name"><b>{{ name }}</b><small>{{ hybridLabel(name) }}</small><dl><div><dt>字段 Recall</dt><dd>{{ percent(hybridProfile(name).routes.column.recall_at_k) }}</dd></div><div><dt>字段 Precision</dt><dd>{{ percent(hybridProfile(name).routes.column.precision_at_k) }}</dd></div><div><dt>长尾 Recall</dt><dd>{{ percent(hybridProfile(name).identifier_subset.recall_at_k) }}</dd></div><div><dt>长尾 MRR</dt><dd>{{ decimal(hybridProfile(name).identifier_subset.mrr) }}</dd></div></dl></article></div>
          <div class="hybrid-deltas"><span>Hybrid vs BGE-M3 Dense</span><b>长尾 Recall {{ signedPercent(report.hybrid.comparison["R-H1_vs_R-D1"].identifier_recall_delta) }}</b><b>长尾 MRR {{ signed(report.hybrid.comparison["R-H1_vs_R-D1"].identifier_mrr_delta) }}</b><small>Embedding P95 {{ numberOrDash(report.hybrid.embedding_latency_ms?.p95) }} ms</small></div>
          <p v-if="report.hybrid.historical_dense_reference?.available" class="historical-reference">覆盖前 Dense 历史制品：{{ report.hybrid.historical_dense_reference.run_id }} · 字段 Recall {{ percent(report.hybrid.historical_dense_reference.column_recall_at_k) }} · Precision {{ percent(report.hybrid.historical_dense_reference.column_precision_at_k) }}</p>
        </template>
        <div v-else class="hybrid-empty"><p>{{ report.hybrid?.message || "先覆盖重建混合索引，再运行真实消融。" }}</p><code>{{ hybridCommand }}</code><button class="btn" type="button" @click="copyHybridCommand">复制混合评测命令</button></div>
      </section>
      <section class="panel point-panel">
        <div class="panel-head"><div><h2>Point 投影策略消融</h2><p>三套隔离 collection 固定 BGE-M3、Dense + Sparse、entity RRF、rule-rerank-v6 与 28 题，只改变实体如何投影成物理 Point。</p></div><span :class="pointReady ? 'pass' : 'fail'">{{ report.point_projection?.available ? (pointReady ? "选择已生效" : "等待门禁/重建") : "尚无投影报告" }}</span></div>
        <template v-if="report.point_projection?.available">
          <div class="point-meta"><code>选择 {{ strategyLabel(report.point_projection.decision.selected_strategy) }}</code><span>评测时 active：{{ strategyLabel(report.point_projection.decision.active_strategy_at_evaluation) }}</span><span>{{ report.point_projection.contract.total }} 条真实检索</span><span>批准别名 {{ report.point_projection.alias_manifest.approved_alias_count }} 个</span><span>固定变量：{{ report.point_projection.frozen_variable }}</span></div>
          <div class="point-grid"><article v-for="name in pointProfiles" :key="name" :class="{ selected: name === report.point_projection.decision.selected_strategy }"><header><div><b>{{ strategyLabel(name) }}</b><small><code>{{ name }}</code></small></div><span :class="pointProfile(name).eligible ? 'mini-pass' : 'mini-fail'">{{ pointProfile(name).eligible ? "合格" : "未通过" }}</span></header><dl><div><dt>实体 / Point</dt><dd>{{ pointManifest(name).entity_count }} / {{ pointManifest(name).point_count }}</dd></div><div><dt>Point/实体</dt><dd>{{ decimal(pointManifest(name).points_per_entity) }}</dd></div><div><dt>重复占位</dt><dd>{{ percent(pointManifest(name).duplicate_occupancy) }}</dd></div><div><dt>字段 Recall</dt><dd>{{ percent(pointSummary(name).routes.column.recall_at_k) }}</dd></div><div><dt>字段 Precision</dt><dd>{{ percent(pointSummary(name).routes.column.precision_at_k) }}</dd></div><div><dt>长尾 MRR</dt><dd>{{ decimal(pointSummary(name).identifier_subset.mrr) }}</dd></div></dl><details><summary>物理角色与合同</summary><p v-for="routeName in pointRoutes" :key="routeName"><b>{{ routeLabel(routeName) }}</b>：{{ roleText(pointManifest(name).routes?.[routeName]?.point_roles) }} · {{ pointManifest(name).routes?.[routeName]?.point_count || 0 }} Point</p></details></article></div>
          <div class="point-decision"><div><strong>{{ report.point_projection.decision.reason }}</strong><small>UUIDv5、向量完整性、租户隔离、歧义误召回和各子集非回退均进入门禁。</small></div><dl><div><dt>Point 变化</dt><dd>{{ signed(pointSelectedDelta.point_count_delta) }}</dd></div><div><dt>字段 Precision</dt><dd>{{ signedPercent(pointSelectedDelta.column_precision_delta) }}</dd></div><div><dt>查询 P95</dt><dd>{{ signed(pointSelectedDelta.query_p95_delta_ms) }} ms</dd></div></dl></div>
        </template>
        <div v-else class="hybrid-empty"><p>{{ report.point_projection?.message || "运行三策略隔离消融后刷新。" }}</p><code>{{ pointCommand }}</code><button class="btn" type="button" @click="copyPointCommand">复制 Point 评测命令</button></div>
      </section>
      <section class="panel capacity-panel" aria-label="Embedding 调度容量对比">
        <div class="panel-head"><div><h2>BGE-M3 Embedding 推理调度</h2><p>固定模型与向量合同，只比较串行调用和单模型有界动态微批；确定性结果不会冒充 GPU 实测。</p></div><span :class="report.embedding_capacity?.summary?.gate_passed ? 'pass' : 'fail'">{{ report.embedding_capacity?.available ? (report.embedding_capacity.summary.gate_passed ? "容量门禁通过" : "容量门禁未通过") : "尚无容量报告" }}</span></div>
        <template v-if="report.embedding_capacity?.available">
          <div class="capacity-meta"><code>{{ report.embedding_capacity.source }}</code><span>{{ report.embedding_capacity.live_model_evaluated ? "真实 BGE-M3 / 当前硬件" : "确定性调度证据" }}</span><span>选择 {{ report.embedding_capacity.summary.selected_runtime_profile }}</span><span>远端服务 {{ report.embedding_capacity.summary.remote_service_triggered ? "已触发" : "未触发" }}</span></div>
          <div class="capacity-grid"><article v-for="name in capacityProfiles" :key="name" :class="{ selected: name === report.embedding_capacity.summary.selected_runtime_profile }"><header><b>{{ capacityLabel(name) }}</b><code>{{ name }}</code></header><dl><div><dt>突发吞吐</dt><dd>{{ numberOrDash(capacityProfile(name).burst_texts_per_second) }} texts/s</dd></div><div><dt>突发耗时</dt><dd>{{ numberOrDash(capacityProfile(name).burst_wall_ms) }} ms</dd></div><div><dt>空闲 Query P95</dt><dd>{{ numberOrDash(capacityProfile(name).idle_query_ms?.p95) }} ms</dd></div><div><dt>模型调用</dt><dd>{{ capacityProfile(name).model_invocations_total ?? "—" }}</dd></div><div><dt>最大模型并发</dt><dd>{{ capacityProfile(name).max_model_concurrency ?? "—" }}</dd></div><div><dt>进程 RSS 峰值</dt><dd>{{ memoryOrDash(capacityResource(name).process?.rss_peak_measured_mb) }}</dd></div><div><dt>推理期 RSS 增长</dt><dd>{{ memoryOrDash(capacityResource(name).process?.measured_peak_growth_mb) }}</dd></div><div><dt>CUDA reserved 峰值</dt><dd>{{ memoryOrDash(capacityResource(name).cuda_measured?.peak_reserved_mb) }}</dd></div></dl></article></div>
          <div class="capacity-decision"><strong>吞吐 {{ numberOrDash(report.embedding_capacity.comparison.burst_texts_per_second_ratio) }}×</strong><span>Query cosine {{ Number(report.embedding_capacity.correctness.query.minimum_dense_cosine || 0).toFixed(8) }}</span><span>空闲 P95 Δ {{ signed(report.embedding_capacity.comparison.idle_query_p95_ms_delta) }} ms</span><span>模型调用 Δ {{ signed(report.embedding_capacity.comparison.model_invocation_delta) }}</span><span>推理期 RSS 增量 Δ {{ signedMemoryOrDash(report.embedding_capacity.comparison.process_rss_growth_mb_delta) }}</span></div>
          <p class="capacity-note">{{ report.embedding_capacity.summary.remote_service_decision }}</p>
        </template>
        <div v-else class="hybrid-empty"><p>{{ report.embedding_capacity?.message || "先生成 Embedding 容量报告。" }}</p><code>{{ capacityCommand }}</code><button class="btn" type="button" @click="copyCapacityCommand">复制容量评测命令</button></div>
      </section>
      <section class="panel signal-panel" aria-label="查询信号消融对比">
        <div class="panel-head"><div><h2>查询信号提取与路由消融</h2><p>完整问题始终保留；K0/K1/K2/K3 分别比较附加信号、远端调用和规则保真，挑战者未通过端到端门禁前不切换 active。</p></div><span :class="report.query_signals?.summary?.gate_passed ? 'pass' : 'fail'">{{ report.query_signals?.available ? (report.query_signals.summary.gate_passed ? "信号门禁通过" : "信号门禁未通过") : "尚无信号报告" }}</span></div>
        <template v-if="report.query_signals?.available">
          <div class="signal-meta"><code>{{ report.query_signals.source }}</code><span>{{ report.query_signals.summary.cases }} 条受控样本</span><span>active {{ report.query_signals.decision.selected_profile }}</span><span>{{ report.query_signals.live?.evaluated ? "已跑真实 RAG" : "尚未跑真实 RAG" }}</span><span>明文 Trace：关闭</span></div>
          <div class="signal-grid"><article v-for="name in signalProfiles" :key="name" :aria-label="`${name} 查询信号方案`" :class="{ selected: querySignalProfile(name).profile === report.query_signals.decision.selected_profile }"><header><div><b>{{ name }} · {{ signalProfileLabel(name) }}</b><code>{{ querySignalProfile(name).profile }}</code></div><span v-if="querySignalProfile(name).profile === report.query_signals.decision.selected_profile" class="mini-pass">ACTIVE</span></header><dl><div><dt>辅助信号 Recall</dt><dd>{{ percent(querySignalProfile(name).auxiliary_recall) }}</dd></div><div><dt>Typed 修饰符</dt><dd>{{ percent(querySignalProfile(name).typed_modifier_recall) }}</dd></div><div><dt>完整问题修饰符</dt><dd>{{ percent(querySignalProfile(name).standalone_modifier_retention) }}</dd></div><div><dt>Column 远端查询</dt><dd>{{ numberOrDash(querySignalProfile(name).routing?.column?.remote_queries_mean) }}</dd></div><div><dt>Value 远端查询</dt><dd>{{ numberOrDash(querySignalProfile(name).routing?.value?.remote_queries_mean) }}</dd></div><div><dt>Extractor Warm P95</dt><dd>{{ numberOrDash(querySignalProfile(name).extractor_latency_ms?.warm_p95) }} ms</dd></div><div><dt>真实 RAG 门禁</dt><dd :class="querySignalLive(name).gate_passed ? 'live-pass' : 'live-fail'">{{ liveSignalStatus(name) }}</dd></div><div><dt>真实字段 Recall</dt><dd>{{ percentOrDash(querySignalLive(name).summary?.column_recall_at_k) }}</dd></div><div><dt>真实 Column 调用</dt><dd>{{ numberOrDash(querySignalLive(name).remote_queries_mean?.column) }}</dd></div></dl></article></div>
          <div class="signal-decision"><div><strong>保留 {{ report.query_signals.decision.selected_profile }}，未自动切换</strong><small>{{ report.query_signals.decision.reason }}</small></div><dl><div><dt>K2 辅助 Recall Δ</dt><dd>{{ signedPercent(report.query_signals.decision.k2_signal_layer_delta_vs_k1?.auxiliary_recall) }}</dd></div><div><dt>K2 Column 调用 Δ</dt><dd>{{ signed(report.query_signals.decision.k2_signal_layer_delta_vs_k1?.column_remote_queries_mean) }}</dd></div><div><dt>租户/隐私</dt><dd>{{ report.query_signals.privacy?.gate_passed ? "通过" : "失败" }}</dd></div><div><dt>批量 Query 编码</dt><dd>{{ report.query_signals.phase0?.checks?.batch_query_api_available ? "固定" : "异常" }}</dd></div></dl></div>
        </template>
        <div v-else class="hybrid-empty"><p>{{ report.query_signals?.message || "先生成查询信号消融报告。" }}</p><code>{{ signalCommand }}</code><button class="btn" type="button" @click="copySignalCommand">复制信号评测命令</button></div>
      </section>
      <section class="panel live-panel">
        <div class="panel-head"><div><h2>真实 full run 证据</h2><p>只读取当前工作空间真实 Qdrant/ES 候选，不用离线词法分替代。</p></div><span :class="report.live?.summary?.gate_passed ? 'pass' : 'fail'">{{ report.live?.available ? (report.live.summary.gate_passed ? "真实门禁通过" : "真实门禁未通过") : "暂无完整 run" }}</span></div>
        <template v-if="report.live?.available">
          <div class="live-grid"><article><span>Run</span><b>{{ report.live.run_id }}</b><small>{{ report.live.summary.evaluated_cases }} / {{ report.live.summary.required_cases }} 条</small></article><article><span>原始字段 Recall / Precision</span><b>{{ percent(report.live.summary.column_recall_at_k) }} / {{ percent(report.live.summary.column_precision_at_k) }}</b><small>真实候选分母</small></article><article><span>最终上下文字段 Recall</span><b>{{ percent(report.live.summary.effective_context_column_recall) }}</b><small>含指标依赖与语义闭包</small></article><article><span>上下文 Token 均值</span><b>{{ numberOrDash(report.live.summary.context_tokens_before_mean) }} → {{ numberOrDash(report.live.summary.context_tokens_after_mean) }}</b><small>压缩 {{ percent(report.live.summary.context_compression_rate) }}</small></article><article><span>候选缓存命中率</span><b>{{ percentOrDash(report.live.summary.candidate_cache_hit_rate) }}</b><small>cold/warm 必须分开看</small></article></div>
          <p v-if="!report.live.summary.budget_evidence_available" class="budget-warning">该 full run 生成于动态预算证据落地前；请按 TODO-41 协议重新运行，才能显示动态 K、缓存和上下文 Token。</p>
          <div v-else class="dynamic-k"><span>平均动态 K</span><code v-for="name in routes" :key="name">{{ routeLabel(name) }} {{ numberOrDash(report.live.summary.average_dynamic_k?.[name]) }}</code></div>
          <div v-if="liveFailedCases.length" class="live-misses" aria-label="真实召回缺口">
            <h3>真实召回缺口（{{ liveFailedCases.length }}）</h3>
            <details v-for="item in liveFailedCases" :key="ragCaseId(item)">
              <summary><code>{{ ragCaseId(item) }}</code><strong>{{ item.query }}</strong></summary>
              <template v-for="name in diagnosticNames" :key="name"><p v-if="item.diagnostics?.[name]?.missing?.length"><b>{{ diagnosticLabel(name) }}</b>：{{ item.diagnostics[name].missing.join('、') }}</p></template>
            </details>
          </div>
        </template>
        <p v-else class="budget-warning">{{ report.live?.message || "尚无可用的真实 full run。" }}</p>
      </section>
      <section class="panel">
        <div class="panel-head"><div><h2>问题级证据</h2><p>展开查看候选表、过滤后表、展示字段和各路 TopK 排名。</p></div><b>{{ filteredCases.length }} / {{ report.tuned.cases.length }}</b></div>
        <form class="filters" aria-label="RAG 用例筛选" @submit.prevent><label>检索问题<input v-model.trim="search" placeholder="用例 ID 或问题" /></label><label>展示字段<select v-model="displayOnly"><option value="">全部</option><option value="hit">已命中</option><option value="miss">未命中</option></select></label></form>
        <div class="case-list"><details v-for="item in filteredCases" :key="ragCaseId(item)" class="case"><summary><i :class="casePassed(item) ? 'passed' : 'failed'"></i><code>{{ ragCaseId(item) }}</code><strong>{{ item.query }}</strong><small>{{ item.filtered_tables.join(' · ') }}</small></summary><div class="case-body"><div><b>筛表链路</b><p>期望：{{ item.expected_tables.join('、') }}</p><p>候选：{{ item.candidate_tables.join('、') }}</p><p>过滤：{{ item.filtered_tables.join('、') }}</p></div><div><b>实体展示字段</b><p>期望：{{ item.display_expected.join('、') || '无' }}</p><p>命中：{{ item.display_hit.join('、') || '无' }}</p></div><div class="rankings"><b>四路 TopK</b><div v-for="name in routes" :key="name"><strong>{{ routeLabel(name) }}</strong><code v-for="candidate in item.routes[name]" :key="candidate.id">#{{ candidate.rank }} {{ candidate.id }} · {{ Number(candidate.rerank_score ?? candidate.score).toFixed(2) }}</code></div></div></div></details></div>
      </section>
      <section class="command"><div><strong>重新生成报告</strong><small>运行后回到本页点“刷新”；如元知识改变，先在元知识页重建索引。</small></div><code>{{ command }}</code></section>
    </template>
    <section v-else-if="report" class="empty"><h2>尚未生成 RAG 报告</h2><p>先在后端目录执行以下命令，再刷新本页。</p><code>{{ command }}</code></section>
  </section>
</template>

<script setup>
import { computed, onMounted, ref } from "vue";
import { requestJson } from "../utils/http.js";
const command = "python -m app.eval.rag_recall --enforce";
const hybridCommand = "python -m app.eval.hybrid_retrieval --workspace-id <workspace-id> --enforce";
const pointCommand = "python -m app.eval.point_projection --workspace-id <workspace-id> --enforce";
const capacityCommand = "python -m app.eval.embedding_capacity --enforce";
const signalCommand = "python -m app.eval.query_signal_ablation --enforce";
const routes = ["column", "metric", "value", "training"];
const pointRoutes = ["column", "metric", "training"];
const hybridProfiles = ["R-D1", "R-S1", "R-H1", "R-H3"];
const pointProfiles = ["single_canonical", "multi_all", "mixed_selective"];
const capacityProfiles = ["serial_inprocess_v1", "microbatch_inprocess_v1"];
const signalProfiles = ["K0", "K1", "K2", "K3"];
const report = ref(null), loading = ref(false), error = ref(""), notice = ref(""), search = ref(""), displayOnly = ref("");
const beforeSummary = computed(() => report.value?.fixed_k?.summary || report.value?.baseline?.summary || { routes: { column: {} } });
const filteredCases = computed(() => (report.value?.tuned?.cases || []).filter(item => { const text = `${item.rag_case_id || ""} ${item.id || ""} ${item.query}`.toLowerCase(); const displayHit = item.display_expected.length === item.display_hit.length; return text.includes(search.value.toLowerCase()) && (!displayOnly.value || (displayOnly.value === "hit") === displayHit); }));
const liveFailedCases = computed(() => (report.value?.live?.cases || []).filter(item => !item.passed));
